const fs = require('fs');
const input = fs.readFileSync(0, 'utf8');
const lines = input.trim().split(/\s+/);

function isPrime(n) {
    if (n <= 1) return false;
    for (let i = 2; i * i <= n; i++) {
        if (n % i === 0) return false;
    }
    return true;
}

lines.forEach(line => {
    if (line !== '') {
        const n = parseInt(line);
        console.log(isPrime(n) ? "Prime" : "Not Prime");
    }
});
